from functools import lru_cache

def earliestAndLatest(n, firstPlayer, secondPlayer):
    @lru_cache(None)
    def dp(n, a, b):
        # a < b are the 1-indexed positions of the two best players in a row of n players.
        # Returns (earliest, latest) round in which they meet, counting this round as 1.
        if a + b == n + 1:           # they are mirror images, so they face each other now
            return (1, 1)
        half = n // 2
        # pair index of each player (pair i is positions i and n+1-i)
        pa, pb = min(a, n + 1 - a), min(b, n + 1 - b)
        free = [i for i in range(1, half + 1) if i != pa and i != pb]
        best_min, best_max = float('inf'), 0
        for mask in range(1 << len(free)):   # choose the winner of every other pair
            survivors = []
            if n % 2:
                survivors.append((n + 1) // 2)   # middle player advances automatically
            for i in range(1, half + 1):
                if i == pa:
                    survivors.append(a)          # the best players always win
                elif i == pb:
                    survivors.append(b)
                else:
                    k = free.index(i)
                    survivors.append(n + 1 - i if (mask >> k) & 1 else i)
            # new positions after re-lining up survivors in ascending order
            na = sum(1 for s in survivors if s <= a)
            nb = sum(1 for s in survivors if s <= b)
            lo, hi = dp(len(survivors), na, nb)
            best_min = min(best_min, lo + 1)
            best_max = max(best_max, hi + 1)
        return (best_min, best_max)

    a, b = sorted((firstPlayer, secondPlayer))
    return list(dp(n, a, b))
